const b = $input.first().json;
return [{ json: {
  channel_id: b.channel_id, workflow_run_id: b.workflow_run_id, content_project_id: b.content_project_id,
  script_version_id: b.script_version_id, provider: b.provider, model: b.model, voice_reference: b.voice_reference,
  settings: b.voice_settings || {}, revision_trigger: b.revision_trigger || 'initial_generation', revision_reason: b.revision_reason || null,
  _ctx: b
} }];

const ctx = $('Prepare Get-Or-Create Input').first().json._ctx;
const goc = $json.data;
const MAX_CHARS = 500;
const WPM = 155;

function applyPronunciation(text, notes) {
  let out = text;
  for (const note of (notes || [])) {
    if (!note || !note.term || !note.note) continue;
    const escaped = note.term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const re = new RegExp('\\b' + escaped + '\\b', 'gi');
    if (re.test(out)) out = out.replace(re, note.note);
  }
  return out;
}

function splitSentences(text) {
  const parts = (text || '').match(/[^.!?]+[.!?]+(\s+|$)|[^.!?]+$/g) || [];
  return parts.map((p) => p.trim()).filter((p) => p.length > 0);
}

const chunks = [];
const perSectionCounter = {};
for (const unit of (ctx.narration_units || [])) {
  const sentences = splitSentences(unit.narration);
  let current = '';
  const flush = () => {
    if (!current.trim()) return;
    const text = current.trim();
    const pronunciationText = applyPronunciation(text, unit.pronunciation_notes);
    const idx = (perSectionCounter[unit.section_id] ?? -1) + 1;
    perSectionCounter[unit.section_id] = idx;
    const wordCount = pronunciationText.split(/\s+/).filter(Boolean).length;
    const estimatedSeconds = Math.max(0.5, (wordCount / WPM) * 60);
    chunks.push({
      section_id: unit.section_id, unit_index: idx, text, pronunciation_text: pronunciationText,
      estimated_duration_seconds: estimatedSeconds,
    });
    current = '';
  };
  for (const sentence of sentences) {
    if (current && (current.length + sentence.length + 1) > MAX_CHARS) { flush(); current = sentence; }
    else { current = current ? current + ' ' + sentence : sentence; }
  }
  flush();
}

return [{ json: {
  channel_id: ctx.channel_id, workflow_run_id: ctx.workflow_run_id, content_project_id: ctx.content_project_id,
  voiceover_id: goc.voiceover_id, version: goc.version, provider: ctx.provider, model: ctx.model, script_version_id: ctx.script_version_id,
  voice_reference: ctx.voice_reference, voice_settings: ctx.voice_settings || {},
  chunks, force_regenerate_chunk_ids: ctx.force_regenerate_chunk_ids || []
} }];

const prep = $input.first().json;
const chunkPlan = $('Chunk Narration').first().json;
return [{ json: { success: true, data: Object.assign({}, prep.data, {
  voiceover_id: chunkPlan.voiceover_id, version: chunkPlan.version, provider: chunkPlan.provider, model: chunkPlan.model,
  voice_reference: chunkPlan.voice_reference, voice_settings: chunkPlan.voice_settings
}), error: null, runtime: prep.runtime } }];
